    public boolean crossDimensionWpTeleportCommand(String instance, String prefix, Operation<Boolean> original, @Local(argsOnly=true) Waypoint waypoint, @Local(argsOnly=true) MinimapWorld world, @Local(name={"fullCommand"}) LocalRef<String> fullCommandRef, @Local(name={"yString"}) String yString) {
