            return (Boolean)original.call(new Object[]{instance, prefix});
        }
        String template = waypoint.isRotation() ? Settings.REGISTRY.crossDimensionWaypointTeleportRotationFormat.get() : Settings.REGISTRY.crossDimensionWaypointTeleportFormat.get();
        ResourceKey dimension = world.getDimId();
        String command = template.replace("{x}", Integer.toString(waypoint.getX())).replace("{y}", yString).replace("{z}", Integer.toString(waypoint.getZ())).replace("{d}", dimension.m_135782_().toString()).replace("{name}", waypoint.getLocalizedName());
